// ============================================================================
// CRITERION 1: Lighting_Radiometry_Visor_Glow_Measurement
// ============================================================================
bool FPlayerCharacterLightingTests::Test_LightingRadiometryVisorGlow(UWorld* World)
{
	if (!World)
	{
		UE_LOG(LogTemp, Error, TEXT("Test_LightingRadiometryVisorGlow: World is null"));
		return false;
	}

	// Step 1: Capture viewport screenshot for color analysis
	FString ScreenshotPath = CaptureViewportScreenshot(TEXT("visor_radiometry_capture"));
	if (ScreenshotPath.IsEmpty())
	{
		UE_LOG(LogTemp, Error, TEXT("Test_LightingRadiometryVisorGlow: Failed to capture viewport"));
		return false;
	}

	// Step 2: Analyze radiometry (RGB, HDR peak, hue)
	FVector CapturedRGB = FVector::ZeroVector;
	float CapturedHDRPeak = 0.0f;
	float CapturedHueDegrees = 0.0f;

	if (!AnalyzeRadiometry(ScreenshotPath, CapturedRGB, CapturedHDRPeak, CapturedHueDegrees))
	{
		UE_LOG(LogTemp, Error, TEXT("Test_LightingRadiometryVisorGlow: Failed to analyze radiometry from screenshot"));
		return false;
	}

	// Step 3: Verify against DSL spec
	// Expected: RGB [0.8, 0.9, 1.0], intensity 0.5, hue 180-240 deg (cool blue)
	const float SpecRGB_R = 0.8f, SpecRGB_G = 0.9f, SpecRGB_B = 1.0f;
	const float SpecIntensity = 0.5f;
	const float SpecHueMin = 180.0f, SpecHueMax = 240.0f;
	const float ToleranceRGB = 0.05f; // ±5% color tolerance
	const float ToleranceIntensity = 0.1f; // ±20% intensity tolerance (0.4-0.6)

	// Check 1: RGB color fidelity within ±0.05 of spec
	float RGBErrorR = FMath::Abs(CapturedRGB.X - SpecRGB_R);
	float RGBErrorG = FMath::Abs(CapturedRGB.Y - SpecRGB_G);
	float RGBErrorB = FMath::Abs(CapturedRGB.Z - SpecRGB_B);
	bool RGBWithinTolerance = (RGBErrorR <= ToleranceRGB) && (RGBErrorG <= ToleranceRGB) && (RGBErrorB <= ToleranceRGB);

	UE_LOG(LogTemp, Display, TEXT("Test_LightingRadiometryVisorGlow: RGB Check"));
	UE_LOG(LogTemp, Display, TEXT("  Spec:      [%.2f, %.2f, %.2f]"), SpecRGB_R, SpecRGB_G, SpecRGB_B);
	UE_LOG(LogTemp, Display, TEXT("  Captured:  [%.2f, %.2f, %.2f]"), CapturedRGB.X, CapturedRGB.Y, CapturedRGB.Z);
	UE_LOG(LogTemp, Display, TEXT("  Error:     [%.3f, %.3f, %.3f] (tolerance: ±%.3f)"), RGBErrorR, RGBErrorG, RGBErrorB, ToleranceRGB);
	UE_LOG(LogTemp, Display, TEXT("  Result:    %s"), RGBWithinTolerance ? TEXT("PASS") : TEXT("FAIL"));

	// Check 2: HDR peak intensity within 0.4-0.6 range (±20% of 0.5)
	float IntensityError = FMath::Abs(CapturedHDRPeak - SpecIntensity);
	bool IntensityWithinTolerance = (CapturedHDRPeak >= SpecIntensity - ToleranceIntensity) &&
		(CapturedHDRPeak <= SpecIntensity + ToleranceIntensity);

	UE_LOG(LogTemp, Display, TEXT("Test_LightingRadiometryVisorGlow: HDR Intensity Check"));
	UE_LOG(LogTemp, Display, TEXT("  Spec:      %.2f (range 0.4-0.6)"), SpecIntensity);
	UE_LOG(LogTemp, Display, TEXT("  Captured:  %.2f"), CapturedHDRPeak);
	UE_LOG(LogTemp, Display, TEXT("  Error:     %.3f (tolerance: ±%.3f)"), IntensityError, ToleranceIntensity);
	UE_LOG(LogTemp, Display, TEXT("  Result:    %s"), IntensityWithinTolerance ? TEXT("PASS") : TEXT("FAIL"));

	// Check 3: Hue within 180-240 degrees (cool blue spectrum)
	bool HueWithinTolerance = (CapturedHueDegrees >= SpecHueMin) && (CapturedHueDegrees <= SpecHueMax);

	UE_LOG(LogTemp, Display, TEXT("Test_LightingRadiometryVisorGlow: Hue Check"));
	UE_LOG(LogTemp, Display, TEXT("  Spec:      %.1f-%.1f degrees (cool blue)"), SpecHueMin, SpecHueMax);
	UE_LOG(LogTemp, Display, TEXT("  Captured:  %.1f degrees"), CapturedHueDegrees);
	UE_LOG(LogTemp, Display, TEXT("  Result:    %s"), HueWithinTolerance ? TEXT("PASS") : TEXT("FAIL"));

	// Final result: all three checks must pass
	bool OverallPass = RGBWithinTolerance && IntensityWithinTolerance && HueWithinTolerance;
	UE_LOG(LogTemp, Display, TEXT("Test_LightingRadiometryVisorGlow: %s"), OverallPass ? TEXT("PASS") : TEXT("FAIL"));

	return OverallPass;
}

