bool FPlayerCharacterLightingTests::Test_LightingContactShadowCloseRange(UWorld* World)
{
	if (!World)
	{
		UE_LOG(LogTemp, Error, TEXT("Test_LightingContactShadowCloseRange: World is null"));
		return false;
	}

	// Step 1: Move camera close to player character (<2m) via MCP
	for (TActorIterator<ACharacter> ActorItr(World); ActorItr; ++ActorItr)
	{
		ACharacter* PlayerChar = *ActorItr;
		if (!PlayerChar)
			continue;

		// Ideally: MCP move_actor to position camera <2m from character head
		// For now: log expected behavior
		FVector CharLocation = PlayerChar->GetActorLocation();
		FVector CameraPosition = CharLocation + FVector(100.0f, 100.0f, 150.0f); // ~2m away, head-level

		UE_LOG(LogTemp, Display, TEXT("Test_LightingContactShadowCloseRange: Camera Setup"));
		UE_LOG(LogTemp, Display, TEXT("  Character location: (%.1f, %.1f, %.1f)"), CharLocation.X, CharLocation.Y, CharLocation.Z);
		UE_LOG(LogTemp, Display, TEXT("  Camera target:      (%.1f, %.1f, %.1f)"), CameraPosition.X, CameraPosition.Y, CameraPosition.Z);

		// Step 2: Capture close-range screenshot
		FString ScreenshotPath = CaptureViewportScreenshot(TEXT("contact_shadow_closeup"));
		if (ScreenshotPath.IsEmpty())
		{
			UE_LOG(LogTemp, Error, TEXT("Test_LightingContactShadowCloseRange: Failed to capture close-range screenshot"));
			return false;
		}

		// Step 3: Analyze close-range visual details
		bool VisorShadows = false, HandRecesses = false, ArtifactFree = false;
		if (!AnalyzeContactShadowVisuals(ScreenshotPath, VisorShadows, HandRecesses, ArtifactFree))
		{
			UE_LOG(LogTemp, Error, TEXT("Test_LightingContactShadowCloseRange: Failed to analyze contact shadow visuals"));
			return false;
		}

		// Log results for all 3 checks
		UE_LOG(LogTemp, Display, TEXT("Test_LightingContactShadowCloseRange: Visual Detail Checks"));
		UE_LOG(LogTemp, Display, TEXT("  Check 1 - Visor shadows under helmet visor: %s"), VisorShadows ? TEXT("PASS") : TEXT("FAIL"));
		UE_LOG(LogTemp, Display, TEXT("  Check 2 - Hand recesses dark/occluded:      %s"), HandRecesses ? TEXT("PASS") : TEXT("FAIL"));
		UE_LOG(LogTemp, Display, TEXT("  Check 3 - No light leaking through geometry: %s"), ArtifactFree ? TEXT("PASS") : TEXT("FAIL"));

		// Final result: all 3 checks must pass
		bool OverallPass = VisorShadows && HandRecesses && ArtifactFree;
		UE_LOG(LogTemp, Display, TEXT("Test_LightingContactShadowCloseRange: %s"), OverallPass ? TEXT("PASS") : TEXT("FAIL"));

		return OverallPass;
	}

	UE_LOG(LogTemp, Warning, TEXT("Test_LightingContactShadowCloseRange: No character found in world"));
	return false;
}

