// CRITERION 5: Lighting_Ambient_Occlusion_Crease_Definition
// ============================================================================
bool FPlayerCharacterLightingTests::Test_LightingAmbientOcclusionCreaseDefinition(UWorld* World)
{
	if (!World)
	{
		UE_LOG(LogTemp, Error, TEXT("Test_LightingAmbientOcclusionCreaseDefinition: World is null"));
		return false;
	}

	// Step 1: Capture character screenshot at optimal angle for AO inspection
	FString ScreenshotPath = CaptureViewportScreenshot(TEXT("ambient_occlusion_detail"));
	if (ScreenshotPath.IsEmpty())
	{
		UE_LOG(LogTemp, Error, TEXT("Test_LightingAmbientOcclusionCreaseDefinition: Failed to capture AO detail screenshot"));
		return false;
	}

	// Step 2: Analyze AO texture quality and crease visibility
	bool NeckCreases = false, KnuckleShading = false, EdgeDefined = false;
	FString AOResolution = TEXT("UNKNOWN");

	if (!AnalyzeAOTextureQuality(ScreenshotPath, NeckCreases, KnuckleShading, EdgeDefined, AOResolution))
	{
		UE_LOG(LogTemp, Error, TEXT("Test_LightingAmbientOcclusionCreaseDefinition: Failed to analyze AO quality"));
		return false;
	}

	// Step 3: Verify all 4 AO quality checks
	// Check 1: Neck/shoulder creases darkened by AO
	UE_LOG(LogTemp, Display, TEXT("Test_LightingAmbientOcclusionCreaseDefinition: AO Crease Visibility"));
	UE_LOG(LogTemp, Display, TEXT("  Check 1 - Neck/shoulder creases darkened: %s"), NeckCreases ? TEXT("PASS") : TEXT("FAIL"));

	// Check 2: Glove knuckles have AO shading
	UE_LOG(LogTemp, Display, TEXT("  Check 2 - Glove knuckles AO-shaded:     %s"), KnuckleShading ? TEXT("PASS") : TEXT("FAIL"));

	// Check 3: Silhouette edges read as 3D
	UE_LOG(LogTemp, Display, TEXT("  Check 3 - Silhouette edges 3D-defined:   %s"), EdgeDefined ? TEXT("PASS") : TEXT("FAIL"));

	// Check 4: AO map resolution adequate (1K+)
	bool ResolutionAdequate = (AOResolution == TEXT("1K") || AOResolution == TEXT("2K") || AOResolution == TEXT("4K"));
	UE_LOG(LogTemp, Display, TEXT("  Check 4 - AO map resolution (1K+):       %s (detected: %s)"),
		ResolutionAdequate ? TEXT("PASS") : TEXT("FAIL"), *AOResolution);

	// Final result: all 4 checks must pass
	bool OverallPass = NeckCreases && KnuckleShading && EdgeDefined && ResolutionAdequate;
	UE_LOG(LogTemp, Display, TEXT("Test_LightingAmbientOcclusionCreaseDefinition: %s"), OverallPass ? TEXT("PASS") : TEXT("FAIL"));

	return OverallPass;
}

