int32 FPlayerCharacterLightingTests::RunAllLightingCriteria(UWorld* World)
{
	int32 PassCount = 0;

	UE_LOG(LogTemp, Display, TEXT("=== PLAYER_CHARACTER LIGHTING ACCEPTANCE TEST SUITE ==="));
	UE_LOG(LogTemp, Display, TEXT("Criteria: 5 lighting fidelity checks (radiometry, shadows, AO)"));

	UE_LOG(LogTemp, Display, TEXT("Criterion 1: Lighting_Radiometry_Visor_Glow_Measurement"));
	if (Test_LightingRadiometryVisorGlow(World))
		PassCount++;

	UE_LOG(LogTemp, Display, TEXT("Criterion 2: Lighting_Shadow_Distance_Profiling"));
	if (Test_LightingShadowDistanceProfiling(World))
		PassCount++;

	UE_LOG(LogTemp, Display, TEXT("Criterion 3: Lighting_Contact_Shadow_Close_Range"));
	if (Test_LightingContactShadowCloseRange(World))
		PassCount++;

	UE_LOG(LogTemp, Display, TEXT("Criterion 4: Lighting_Dynamic_Shadow_Update_Rate"));
	if (Test_LightingDynamicShadowUpdateRate(World))
		PassCount++;

	UE_LOG(LogTemp, Display, TEXT("Criterion 5: Lighting_Ambient_Occlusion_Crease_Definition"));
	if (Test_LightingAmbientOcclusionCreaseDefinition(World))
		PassCount++;

	UE_LOG(LogTemp, Display, TEXT("=== RESULTS: %d/5 lighting criteria passed ==="), PassCount);
	UE_LOG(LogTemp, Display, TEXT("Note: Criteria 4-5 partially deferred to sleepwalker simulation (PIE + real-time measurement)"));

	return PassCount;
}

