// Logging macro for evidence capture
#define LOG_LIGHTING_TEST(TestName, Result, Details) \
	UE_LOG(LogTemp, Display, TEXT("LIGHTING_TEST:%s:%s:%s"), TEXT(TestName), (Result) ? TEXT("PASS") : TEXT("FAIL"), TEXT(Details))
